# This file is usually generated by the Flutter tool. 
# It is required for the Podfile to function.

def flutter_install_all_ios_pods(relative_project_root)
  flutter_root = File.expand_path(File.join('..', '..', '..'), __FILE__)
  if File.exist?(File.join(relative_project_root, 'Flutter', 'Generated.xcconfig'))
    File.foreach(File.join(relative_project_root, 'Flutter', 'Generated.xcconfig')) do |line|
      matches = line.match(/\AFLUTTER_ROOT=(.*)\z/)
      if matches
        flutter_root = matches[1].strip
        break
      end
    end
  end

  podhelper_path = File.join(flutter_root, 'packages', 'flutter_tools', 'bin', 'podhelper.rb')
  load podhelper_path
  flutter_additional_ios_build_settings(target) if defined?(flutter_additional_ios_build_settings)
end